    "change_intelligence.delay.tile.high": "Élevé",
    "change_intelligence.delay.tile.elevated": "Accru",
    "change_intelligence.delay.tile.low": "Faible",
    "change_intelligence.delay.empty_title": "Aucun changement ouvert",
    "change_intelligence.delay.empty_desc": "Il n'y a aucun changement ouvert à noter pour le risque de retard pour le moment.",
    "change_intelligence.delay.risk_pct": "{{pct}} % de risque",
    "change_intelligence.delay.overdue": "en retard",
    "change_intelligence.delay.held_by": "Détenu par {{party}}",
