    "risk.boq_empty": "Ce DQE ne contient encore aucune position chiffrée. Ajoutez des positions avec coûts pour lancer une simulation.",
    "risk.positions_loaded_msg": "{{count}} positions avec coûts prêtes pour la simulation",
    "risk.default_optimistic": "Optimiste par défaut",
    "risk.default_pessimistic": "Pessimiste par défaut",
